#!/usr/bin/env python3
"""RL-FullGuard-C as a standalone Axelrod strategy.

This is a faithful single-file port of the pri_dile candidate
``rl-full-guard-c``: RL-V5-FT-Complex (160/128, 85 features) plus the
reactive probe/late guard from ``ipd/policies/meta.py``.

Guard behaviour (reactive, no proactive defection):

* probe window: the opponent's first D is at zero-based round 5 or 7,
  confirmed by three consecutive D, then play C, C, C;
* late window: the opponent's first D is at zero-based round 9 or later,
  confirmed by three consecutive D, then play D, C, C;
* any cooperative reply releases back to the base policy;
* punishment continues until the opponent cooperates.

The base model is the V5-FT-Complex deployable MLP embedded below, so this
file has no external data dependencies.  Only the stochastic ``sample``
mode is supported, matching the pri_dile deployment contract.

Development/evaluation payoff matrix: T=10, R=6, P=1, S=0.
Use the module-level ``GAME`` with axelrod Match/Tournament.
"""
from __future__ import annotations

import base64
import json
import math
import random
import zlib
from operator import mul
from typing import Sequence

from axelrod import Action, Game, Player

# Development/evaluation payoff matrix: T=10, R=6, P=1, S=0.
GAME = Game(r=6, s=0, t=10, p=1)

# Internal action convention used by the original pri_dile policies.
C = 0
D = 1

# Axelrod action objects.
A_C = Action.C
A_D = Action.D


def _histories(player, opponent):
    mine = [D if move == A_D else C for move in player.history]
    theirs = [D if move == A_D else C for move in opponent.history]
    if len(mine) != len(theirs):
        raise RuntimeError("history lengths differ")
    return mine, theirs


def _require_sample(mode, name):
    if mode != "sample":
        raise ValueError(f"{name} supports only 'sample' mode")

